def count_neighbors_of_type(pos, grid, neighbor_type):
    r, c = pos
    count = 0
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < 13 and 0 <= nc < 13:
