def apply_transformation(grid):
    # Copy input
    result = [row[:] for row in grid]

    # Convert all 0s with at least one 0-neighbor to 8
    changed = True
    while changed:
        changed = False
        new_changes = []

        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if result[i][j] == 0:
                    # Count orthogonal zero neighbors
                    has_zero_neighbor = False
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ni, nj = i + dr, j + dc
                        if 0 <= ni < len(grid) and 0 <= nj < len(grid[0]):
                            if grid[ni][nj] == 0:
                                has_zero_neighbor = True
                                break

                    if has_zero_neighbor:
                        if result[i][j] != 8:
                            result[i][j] = 8
                            new_changes.append((i,j))

        # If we made changes, do expansion
        if new_changes:
            # Expand to all orthogonal 1-neighbors of current 8s
            while True:
                changed_ones = []
                for i, j in new_changes:
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ni, nj = i + dr, j + dc
                        if 0 <= ni < len(grid) and 0 <= nj < len(grid[0]):
                            if result[ni][nj] == 1:
                                if result[ni][nj] != 8:
                                    result[ni][nj] = 8
                                    changed_ones.append((ni, nj))
                if not changed_ones:
                    break
                new_changes.extend(changed_ones)
        else:
            break

    return result

